import os
import requests

BASE_URL = os.environ.get("API_BASE_URL", "https://api.socbench.example").rstrip("/")
session = requests.Session()
session.headers.update({"Accept": "application/json"})

# Supply the required identifiers and date range through environment variables.
statistics_response = session.get(
    f"{BASE_URL}/statistics",
    params={
        "start_date": os.environ["START_DATE"],  # YYYY-MM-DD
        "end_date": os.environ["END_DATE"],      # YYYY-MM-DD
    },
)
statistics_response.raise_for_status()
attendance_statistics = statistics_response.json()

itinerary_response = session.put(
    f"{BASE_URL}/itinerary/modify",
    json={
        "userId": os.environ["USER_ID"],
        "itineraryId": os.environ["ITINERARY_ID"],
        "updates": {
            "sustainableTravelOptions": True,
            "preferences": [
                "prioritize public transit",
                "prefer rail over air where practical",
                "choose lower-emission travel options",
            ],
            "initiativeAlignment": "sustainability-focused initiative",
        },
    },
)
itinerary_response.raise_for_status()

manufacturer_response = session.post(
    f"{BASE_URL}/manufacturers/register",
    json={
        "name": os.environ["ORGANIZATION_NAME"],
        "location": os.environ["ORGANIZATION_LOCATION"],
        "contactInfo": {
            "email": os.environ["ORGANIZATION_EMAIL"],
            **(
                {"phone": os.environ["ORGANIZATION_PHONE"]}
                if os.environ.get("ORGANIZATION_PHONE")
                else {}
            ),
        },
    },
)
manufacturer_response.raise_for_status()
manufacturer = manufacturer_response.json()

# The documented API has no endpoint for deleting material records.
# Send the planned updates and sustainability measures to event stakeholders.
notification_response = session.post(
    f"{BASE_URL}/notifications",
    json={
        "eventId": os.environ["EVENT_ID"],
        "message": (
            "Planned updates: attendance statistics are being used to guide "
            "initiative planning, the travel itinerary is being updated to "
            "prioritize sustainable travel options, and the organization is "
            "registering for sustainability tracking. Outdated material records "
            "cannot be removed through the currently documented API."
        ),
    },
)
notification_response.raise_for_status()

